const euro=n=>new Intl.NumberFormat("fr-FR",{style:"currency",currency:"EUR"}).format(Number(n||0)).replace(",00","");

function normalizeImageFile(file,maxW=1600,maxH=1100,quality=.9){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=reject;
    reader.onload=()=>{
      const img=new Image();
      img.onerror=reject;
      img.onload=()=>{
        let w=img.naturalWidth||img.width, h=img.naturalHeight||img.height;
        const scale=Math.min(1,maxW/w,maxH/h);
        const nw=Math.max(1,Math.round(w*scale)), nh=Math.max(1,Math.round(h*scale));
        const c=document.createElement("canvas");
        c.width=nw;c.height=nh;
        const ctx=c.getContext("2d");
        ctx.fillStyle="#ffffff";
        ctx.fillRect(0,0,nw,nh);
        ctx.drawImage(img,0,0,nw,nh);
        resolve(c.toDataURL("image/jpeg",quality));
      };
      img.src=reader.result;
    };
    reader.readAsDataURL(file);
  });
}


function finishCodeFromReference(ref){
  const m=String(ref||"").match(/\.(BS|BB|BC)$/i);
  return m?m[1].toUpperCase():"";
}
function exactFinishLabel(p){
  const code=finishCodeFromReference(p.reference);
  return code ? `${code} · ${p.finish}` : p.finish;
}
function preferredImageFor(p){
  // Never silently show a catalogue image for a finish variant:
  // it could depict the wrong finish.
  if(p.manufacturerImage) return {src:p.manufacturerImage,source:"Site fabricant · finition exacte",quality:"exact"};
  if(p.manufacturerGenericImage) return {src:p.manufacturerGenericImage,source:"Site fabricant · visuel générique",quality:"generic"};
  return {src:"",source:"Photo fabricant à récupérer",quality:"missing"};
}
function useCatalogueFallback(productId){
  const p=state.selected.find(x=>x.id===productId);
  if(!p || !p.fallbackImage) return;
  p.image=p.fallbackImage;
  p.imageSource="Catalogue fabricant · visuel de secours";
  p.customImage=false;
  saveState();renderRooms();
}




const HYDRO_ASSET_DB="hydropolis-assets-v1";
function assetDb(){
  return new Promise((resolve,reject)=>{
    const req=indexedDB.open(HYDRO_ASSET_DB,1);
    req.onupgradeneeded=()=>{
      const db=req.result;
      if(!db.objectStoreNames.contains("assets"))db.createObjectStore("assets");
    };
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error);
  });
}
async function assetSet(key,blob){
  const db=await assetDb();
  return new Promise((resolve,reject)=>{
    const tx=db.transaction("assets","readwrite");
    tx.objectStore("assets").put(blob,key);
    tx.oncomplete=()=>resolve(true);
    tx.onerror=()=>reject(tx.error);
  });
}
async function assetGet(key){
  const db=await assetDb();
  return new Promise((resolve,reject)=>{
    const tx=db.transaction("assets","readonly");
    const req=tx.objectStore("assets").get(key);
    req.onsuccess=()=>resolve(req.result||null);
    req.onerror=()=>reject(req.error);
  });
}
async function assetDelete(key){
  const db=await assetDb();
  return new Promise((resolve,reject)=>{
    const tx=db.transaction("assets","readwrite");
    tx.objectStore("assets").delete(key);
    tx.oncomplete=()=>resolve(true);
    tx.onerror=()=>reject(tx.error);
  });
}
async function hydrateCustomAssets(){
  let changed=false;
  for(const p of state.selected||[]){
    try{
      if(p.customImage){
        const blob=await assetGet(`photo:${p.id}`);
        if(blob){
          const url=URL.createObjectURL(blob);
          p.image=url;p.images=[url];p.pdfImage=url;p.pdfImages=[url];
          changed=true;
        }
      }
      if(p.customTechnicalSheet){
        const blob=await assetGet(`tech:${p.id}`);
        if(blob){
          p.technicalSheetUrl=URL.createObjectURL(blob);
          p.technicalSheetType="pdf";
          changed=true;
        }
      }
    }catch(e){
      console.warn("[hydrate asset]",p.id,e);
    }
  }
  return changed;
}

async function autoCropForPdf(src){
  return new Promise((resolve)=>{
    const img=new Image();
    img.onload=()=>{
      try{
        const maxScan=1400;
        const scale=Math.min(1,maxScan/img.naturalWidth,maxScan/img.naturalHeight);
        const w=Math.max(1,Math.round(img.naturalWidth*scale));
        const h=Math.max(1,Math.round(img.naturalHeight*scale));
        const c=document.createElement("canvas"); c.width=w;c.height=h;
        const ctx=c.getContext("2d",{willReadFrequently:true});
        ctx.drawImage(img,0,0,w,h);
        const d=ctx.getImageData(0,0,w,h).data;
        let minX=w,minY=h,maxX=-1,maxY=-1;
        for(let y=0;y<h;y++){
          for(let x=0;x<w;x++){
            const i=(y*w+x)*4, a=d[i+3], r=d[i], g=d[i+1], b=d[i+2];
            // White/transparent background is ignored. Product + natural shadow are retained.
            const visible=a>18 && !(r>246 && g>246 && b>246);
            if(visible){
              if(x<minX)minX=x;if(x>maxX)maxX=x;
              if(y<minY)minY=y;if(y>maxY)maxY=y;
            }
          }
        }
        if(maxX<minX || maxY<minY){resolve(src);return;}
        const bw=maxX-minX+1,bh=maxY-minY+1;
        const pad=Math.round(Math.max(bw,bh)*0.055);
        minX=Math.max(0,minX-pad);minY=Math.max(0,minY-pad);
        maxX=Math.min(w-1,maxX+pad);maxY=Math.min(h-1,maxY+pad);
        const cw=maxX-minX+1,ch=maxY-minY+1;
        const out=document.createElement("canvas");
        // Keep enough resolution for A4 PDF output.
        const targetScale=Math.min(2.2,1800/Math.max(cw,ch));
        out.width=Math.max(1,Math.round(cw*targetScale));
        out.height=Math.max(1,Math.round(ch*targetScale));
        const o=out.getContext("2d");
        o.fillStyle="#ffffff";o.fillRect(0,0,out.width,out.height);
        o.drawImage(c,minX,minY,cw,ch,0,0,out.width,out.height);
        resolve(out.toDataURL("image/jpeg",0.94));
      }catch(e){resolve(src);}
    };
    img.onerror=()=>resolve(src);
    img.src=src;
  });
}

