function roomById(id){return state.rooms.find(r=>r.id===id)}
function renderRoomSelect(){let cur=$("#targetRoom")?.value||state.rooms[0].id;$("#targetRoom").innerHTML=state.rooms.map(r=>`<option value="${r.id}">${r.title}</option>`).join(""); if(state.rooms.some(r=>r.id===cur))$("#targetRoom").value=cur;}
function matches(p,q){let hay=[p.reference,p.base,p.designation,p.collection,p.manufacturer,p.finish,p.category].join(" ").toLowerCase();return q.toLowerCase().trim().split(/\s+/).filter(Boolean).every(w=>hay.includes(w));}
function renderCatalog(){
 const results=$("#results");
 const count=$("#resultCount");
 if(!results)return;

 try{
   let q=$("#searchInput")?.value||"";
   let fs={
     manufacturer:$("#manufacturerFilter")?.value||"",
     collection:$("#collectionFilter")?.value||"",
     category:$("#categoryFilter")?.value||"",
     finish:$("#finishFilter")?.value||""
   };
   let rows=CATALOG.filter(p=>{
     try{
       return matches(p,q)&&Object.entries(fs).every(([k,v])=>!v||p?.[k]===v);
     }catch(e){
       console.warn("[catalog row ignored]",p?.reference,e);
       return false;
     }
   });

   if(count)count.textContent=rows.length+" résultat"+(rows.length>1?"s":"");
   let room=roomById($("#targetRoom")?.value)||state.rooms[0];

   const cards=[];
   for(const p of rows.slice(0,100)){
     try{
       const cached=cachedManufacturerImage(p);
       const finishLabel=exactFinishLabel(p)||"";
       const price=Number(p.totalPrice||0);
       cards.push(`<article class="result">
       <div class="catalog-thumb">${cached?.src?`<img src="${cached.src}" alt="${p.reference||""}">`:`<div class="photo-missing"><b>Photo fabricant</b><br>${finishLabel}<br>à rechercher</div>`}</div>
       <div><div class="r-top"><span class="ref">${p.reference||""}</span><span class="badge">${p.manufacturer||""}</span><span class="badge">${p.collection||""}</span><span class="badge">${p.category||""}</span></div>
       <div class="designation">${p.designation||""}</div><div class="meta">${p.finish||""}</div>
       <div class="manufacturer-tools">
         <button class="tiny lookup-photo" data-ref="${p.reference||""}">${cached?"Actualiser la photo":"Trouver la photo fabricant"}</button>
         ${p.manufacturerUrl?`<a class="source-link" target="_blank" href="${cached?.resolvedManufacturerUrl||p.manufacturerUrl}">Fiche officielle ↗</a>`:""}
         ${cached?.technicalSheetUrl?`<a class="source-link technical-sheet-link" target="_blank" href="${cached.technicalSheetUrl}">Fiche technique ↗</a>`:""}
         ${cached?.drawingUrl?`<a class="source-link drawing-result-link" target="_blank" href="${cached.drawingUrl}">Drawing 2D ↗</a>`:""}
       </div>
       <div class="photo-status">${cached?`<b>${imageBadge(cached,p)}</b>${cached.note?`<br>${cached.note}`:""}`:`Priorité au site officiel du fabricant.`}</div>
       </div>
       <div class="price-box"><div class="price">${euro(price)} HT</div>
       ${p.internalReference?`<div class="internal">Ext. ${euro(p.price)} + ${p.internalReference} ${euro(p.internalPrice)}<br><b>interne ajouté automatiquement</b></div>`:`<div class="internal">Référence complète</div>`}
       ${isRecorBathRequiringFeet(p)?`<div class="internal recor-config-hint"><b>Pieds obligatoires</b> · choix à l’ajout</div>`:""}
       <button class="btn primary add" data-ref="${p.reference||""}" style="margin-top:9px">${isRecorBathRequiringFeet(p)?"Configurer + ajouter":"Ajouter à "+(room?.title||"la pièce")}</button></div>
       </article>`);
     }catch(e){
       console.error("[catalog card]",p?.reference,e);
     }
   }

   results.innerHTML=cards.join("")||`<div class="empty">Aucun résultat.</div>`;
   $$(".add").forEach(b=>b.onclick=()=>addCatalogProduct(b.dataset.ref,$("#targetRoom").value));
   $$(".lookup-photo").forEach(b=>b.onclick=()=>lookupCatalogPhoto(b.dataset.ref,b));
 }catch(e){
   console.error("[renderCatalog]",e);
   if(count)count.textContent="Erreur d’affichage du catalogue";
   results.innerHTML=`<div class="empty"><b>Le catalogue n’a pas pu s’afficher.</b><br>Rechargez la page. Si le problème persiste, la console indique la référence en cause.</div>`;
 }
}

function accessoryText(p){
  return [p.designation,p.marketingDescription,p.originalDescription,p.category,p.collection]
    .filter(Boolean).join(" ").toLowerCase();
}
function isBasinTap(p){
  if(!p || p.category!=="Lavabo") return false;
  const t=accessoryText(p);
  if(/bonde|waste|siphon|trap|vidage|accessoire|spare|replacement/.test(t)) return false;
  return /mitigeur|mélangeur|robinet|mixer|faucet|basin tap|bec lavabo|basin spout/.test(t);
}
function accessoryKind(p){
  const t=accessoryText(p);
  const spare=/replacement|spare|part of|body|locknut|rod|tube|sleeve|cap\b|vitone|deviatore/.test(t);
  if(spare) return "";
  if(/siphon|bottle trap/.test(t) && !/without trap/.test(t)) return "siphon";
  if(/bonde|basin waste|lavabo waste|waste/.test(t) && !/shower tray|bath|baignoire|without trap/.test(t)) return "bonde";
  return "";
}
function compatibleFinish(source,candidate){
  if(!source.finish) return true;
  if(candidate.finish===source.finish) return true;
  if(source.finishCode && candidate.finishCode && source.finishCode===candidate.finishCode) return true;
  return false;
}
function accessoryScore(source,candidate,kind){
  let score=0;
  if(candidate.manufacturer===source.manufacturer) score+=1000;
  if(compatibleFinish(source,candidate)) score+=500;
  else return -9999;
  if(accessoryKind(candidate)===kind) score+=300;
  if(candidate.collection===source.collection) score+=35;
  const t=accessoryText(candidate);
  if(kind==="siphon"){
    if(/siphon bouteille|bottle trap/.test(t)) score+=90;
    if(/lavabo|basin/.test(t)) score+=60;
  }
  if(kind==="bonde"){
    if(/bonde|basin waste|lavabo waste/.test(t)) score+=90;
    if(/clic.?clac|click.?clack|free flow|écoulement libre/.test(t)) score+=40;
    if(/lavabo|basin/.test(t)) score+=60;
  }
  if(candidate.price>0) score+=5;
  return score;
}
function matchingAccessory(source,kind){
  return CATALOG
    .filter(c=>c.reference!==source.reference && c.manufacturer===source.manufacturer && accessoryKind(c)===kind)
    .map(c=>({c,score:accessoryScore(source,c,kind)}))
    .filter(x=>x.score>0)
    .sort((x,y)=>y.score-x.score || String(x.c.reference).localeCompare(String(y.c.reference)))[0]?.c||null;
}
function basinAccessorySuggestions(p,roomId){
  if(!isBasinTap(p)) return "";
  const siphon=matchingAccessory(p,"siphon");
  const bonde=matchingAccessory(p,"bonde");
  const selectedRefs=new Set(state.selected.filter(x=>x.roomId===roomId).map(x=>x.reference));

  const option=(kind,item)=>{
    const label=kind==="siphon"?"Siphon assorti":"Bonde assortie";
    if(!item) return `<div class="accessory-option unavailable"><div><b>${label}</b><span>Aucune référence assortie identifiée dans le tarif ${p.manufacturer}.</span></div></div>`;
    const already=selectedRefs.has(item.reference);
    return `<div class="accessory-option">
      <div><b>${label}</b><span>${item.designation} · ${item.reference} · ${item.finish||p.finish}</span></div>
      <div class="accessory-option-right"><strong>${euro(item.totalPrice)} HT</strong>
      ${already?`<span class="accessory-added">Déjà ajouté</span>`:`<button class="tiny add-accessory" data-ref="${item.reference}" data-room="${roomId}" data-parent="${p.id}">+ Ajouter</button>`}</div>
    </div>`;
  };

  return `<div class="basin-accessories">
    <div class="basin-accessories-head"><b>Compléments lavabo assortis</b><span>Suggestions uniquement — ajoutées au dossier seulement après clic sur « + Ajouter »</span></div>
    ${option("siphon",siphon)}
    ${option("bonde",bonde)}
  </div>`;
}


function isRecorBathRequiringFeet(p){
  return p?.manufacturer==="Recor" && p?.category==="Bain" && p?.collection==="Baignoires sur pieds" && !/collins/i.test(`${p.reference||""} ${p.designation||""}`);
}
function recorModelName(p){
  const hay=normalizeText(`${p?.reference||""} ${p?.designation||""} ${p?.originalDescription||""}`);
  const models=["Roll Top","Carlton","Dual","Antique","Primrose","Slipper","Hudson","Lyra"];
  return models.find(m=>hay.includes(normalizeText(m)))||"";
}
function recorCompatibleFeet(p){
  const model=recorModelName(p);
  if(!model)return [];
  return CATALOG.filter(c=>c.manufacturer==="Recor" && c.collection==="Pieds Recor" && normalizeText(c.supplierNote||"").includes(normalizeText(model)))
    .sort((a,b)=>String(a.designation).localeCompare(String(b.designation),"fr") || String(a.finish).localeCompare(String(b.finish),"fr"));
}
function recorCompatibleWastes(p){
  const model=recorModelName(p);
  return CATALOG.filter(c=>{
    if(c.manufacturer!=="Recor" || c.collection!=="Accessoires Recor")return false;
    const t=normalizeText(`${c.designation||""} ${c.originalDescription||""}`);
    if(!/vidage|waste/.test(t))return false;
    const note=normalizeText(c.supplierNote||"");
    if(/vidage classique|classic bathtub waste/.test(t)){
      const excluded=["Gibson","Collins","Carlton","Siena","Epoque","Eiffel","Chateau","Moritz","Hudson"];
      if(excluded.some(x=>normalizeText(model)===normalizeText(x)))return false;
    }
    return true;
  }).sort((a,b)=>String(a.designation).localeCompare(String(b.designation),"fr") || String(a.finish).localeCompare(String(b.finish),"fr"));
}
function recorFeetSelected(p){
  return state.selected.some(x=>x.roomId===p.roomId && x.accessoryFor===p.id && x.manufacturer==="Recor" && x.collection==="Pieds Recor");
}
function recorBathOptions(p,roomId){
  if(!isRecorBathRequiringFeet(p))return "";
  const feet=recorCompatibleFeet(p), wastes=recorCompatibleWastes(p);
  const linked=state.selected.filter(x=>x.roomId===roomId && x.accessoryFor===p.id);
  const selectedRefs=new Set(linked.map(x=>x.reference));
  const option=(item,required=false)=>`<div class="accessory-option">
    <div><b>${item.designation}</b><span>${item.finish||""} · ${item.reference}</span></div>
    <div class="accessory-option-right"><strong>${euro(item.totalPrice)} HT</strong>${selectedRefs.has(item.reference)?`<span class="accessory-added">Sélectionné</span>`:`<button class="tiny add-accessory" data-ref="${item.reference}" data-room="${roomId}" data-parent="${p.id}">+ Choisir</button>`}</div>
  </div>`;
  const hasFeet=recorFeetSelected(p);
  return `<div class="basin-accessories recor-bath-options ${hasFeet?"":"required-missing"}">
    <div class="basin-accessories-head"><b>Pieds Recor ${hasFeet?"✓":"— choix obligatoire"}</b><span>Choisir un jeu de pieds compatible avec ${recorModelName(p)||"cette baignoire"}.</span></div>
    ${feet.length?feet.map(x=>option(x,true)).join(""):`<div class="accessory-option unavailable"><div><b>Pieds compatibles non identifiés</b><span>Vérifier le modèle Recor.</span></div></div>`}
    <div class="basin-accessories-head recor-option-head"><b>Vidage Recor</b><span>Suggestion optionnelle — ajoutée au dossier uniquement si sélectionnée.</span></div>
    ${wastes.length?wastes.map(x=>option(x,false)).join(""):`<div class="accessory-option unavailable"><div><b>Aucun vidage compatible identifié</b></div></div>`}
  </div>`;
}
function incompleteRecorBaths(){
  return state.selected.filter(p=>isRecorBathRequiringFeet(p) && !recorFeetSelected(p));
}
function validateRecorFeet(showAlert=true){
  const missing=incompleteRecorBaths();
  if(!missing.length)return true;
  if(showAlert)alert(`Choix incomplet : ${missing.length} baignoire${missing.length>1?"s Recor n'ont":" Recor n'a"} pas encore de pieds. Dans « Projet par pièce », choisissez un jeu de pieds dans le bloc Recor sous la baignoire.`);
  return false;
}


function recorOptionDisplay(item){
  const extra=item.finish?` · ${item.finish}`:"";
  return `${item.designation}${extra}`;
}
function closeRecorConfigurator(){
  const el=document.getElementById("recorConfigurator");
  if(el)el.remove();
}
function openRecorBathConfigurator(p,roomId){
  const feet=recorCompatibleFeet(p);
  const wastes=recorCompatibleWastes(p);
  closeRecorConfigurator();

  const overlay=document.createElement("div");
  overlay.id="recorConfigurator";
  overlay.className="recor-configurator-overlay";
  overlay.innerHTML=`<div class="recor-configurator" role="dialog" aria-modal="true" aria-labelledby="recorConfigTitle">
    <div class="recor-config-head">
      <div><div class="eyebrow">Recor · configuration obligatoire</div><h2 id="recorConfigTitle">${p.designation}</h2><p>Choisissez les pieds avant d’ajouter la baignoire au projet. Le vidage reste optionnel.</p></div>
      <button type="button" class="icon recor-config-close" aria-label="Fermer">×</button>
    </div>
    <div class="recor-config-summary"><b>${euro(p.totalPrice)} HT</b><span>${p.mandatoryFreight?`dont ${euro(p.mandatoryFreight)} de transport Recor obligatoire`:'Transport selon tarif'}</span></div>
    <div class="recor-config-section">
      <div class="recor-config-title"><b>1. Pieds</b><span>Obligatoire — un seul choix</span></div>
      <div class="recor-choice-list">
        ${feet.length?feet.map((x,i)=>`<label class="recor-choice required-choice">
          <input type="radio" name="recorFeet" value="${x.reference}" ${i===0?'':''}>
          <span class="recor-choice-main"><b>${recorOptionDisplay(x)}</b><small>${x.reference}</small></span>
          <strong>${euro(x.totalPrice)} HT</strong>
        </label>`).join(''):`<div class="recor-no-choice">Aucun pied compatible n’a été identifié pour ce modèle.</div>`}
      </div>
    </div>
    <div class="recor-config-section">
      <div class="recor-config-title"><b>2. Vidage</b><span>Optionnel — vous pouvez ne rien sélectionner</span></div>
      <div class="recor-choice-list optional-list">
        ${wastes.length?wastes.map(x=>`<label class="recor-choice">
          <input type="checkbox" name="recorWaste" value="${x.reference}">
          <span class="recor-choice-main"><b>${recorOptionDisplay(x)}</b><small>${x.reference}</small></span>
          <strong>${euro(x.totalPrice)} HT</strong>
        </label>`).join(''):`<div class="recor-no-choice">Aucun vidage compatible identifié.</div>`}
      </div>
    </div>
    <div class="recor-config-error" aria-live="polite"></div>
    <div class="recor-config-actions">
      <button type="button" class="btn ghost recor-config-cancel">Annuler</button>
      <button type="button" class="btn primary recor-config-confirm" ${feet.length?'':'disabled'}>Ajouter baignoire + sélection</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);

  const close=()=>closeRecorConfigurator();
  overlay.querySelector('.recor-config-close').onclick=close;
  overlay.querySelector('.recor-config-cancel').onclick=close;
  overlay.addEventListener('click',e=>{if(e.target===overlay)close();});

  const confirmBtn=overlay.querySelector('.recor-config-confirm');
  if(confirmBtn)confirmBtn.onclick=async()=>{
    const foot=overlay.querySelector('input[name="recorFeet"]:checked');
    const err=overlay.querySelector('.recor-config-error');
    if(!foot){
      err.textContent='Sélectionnez obligatoirement un jeu de pieds.';
      return;
    }
    err.textContent='';
    confirmBtn.disabled=true;
    confirmBtn.textContent='Ajout en cours…';
    try{
      const bathId=await addProduct(p.reference,roomId,'');
      if(!bathId)throw new Error('La baignoire n’a pas pu être ajoutée.');
      await addProduct(foot.value,roomId,bathId);
      const wasteRefs=[...overlay.querySelectorAll('input[name="recorWaste"]:checked')].map(x=>x.value);
      for(const ref of wasteRefs)await addProduct(ref,roomId,bathId);
      closeRecorConfigurator();
      showView('project');
    }catch(e){
      console.error('[Recor configurator]',e);
      err.textContent=e.message||'Impossible d’ajouter la configuration.';
      confirmBtn.disabled=false;
      confirmBtn.textContent='Ajouter baignoire + sélection';
    }
  };
  overlay.querySelector('input[name="recorFeet"]')?.focus();
}
function addCatalogProduct(ref,roomId){
  const p=CATALOG.find(x=>x.reference===ref);
  if(!p)return;
  if(isRecorBathRequiringFeet(p)){
    openRecorBathConfigurator(p,roomId);
    return;
  }
  addProduct(ref,roomId);
}

async function addProduct(ref,roomId,parentId=""){
 const p=CATALOG.find(x=>x.reference===ref);if(!p)return;
 const cached=cachedManufacturerImage(p);
 const id=crypto.randomUUID?crypto.randomUUID():Math.random().toString(36);

 state.selected.push({
   ...p,id,roomId,
   catalogPrice:Number(p.price||0),
   catalogTotalPrice:Number(p.totalPrice||0),
   priceOverride:null,
   originalDesignation:p.designation||"",
   customTechnicalSheet:false,
   image:cached?.src||"",
   images:cached?.images||[cached?.src].filter(Boolean),
   pdfImage:cached?.src||"",
   pdfImages:cached?.images||[cached?.src].filter(Boolean),
   remoteImageUrl:cached?.remoteUrl||"",
   remoteImages:cached?.remoteImages||[],
   imageSource:cached?.source||"Photo fabricant à rechercher",
   imageFinishMatch:cached?.finishMatch||"",
   imageStatus:cached?imageBadge(cached,p):"Recherche fabricant…",
   resolvedManufacturerUrl:cached?.resolvedManufacturerUrl||p.manufacturerUrl||"",
   drawingUrl:cached?.drawingUrl||"",
   drawingType:cached?.drawingType||"",
   drawingLabel:cached?.drawingLabel||"",
   technicalSheetUrl:cached?.technicalSheetUrl||"",
   technicalSheetLabel:cached?.technicalSheetLabel||"Fiche technique",
   installationGuideUrl:cached?.installationGuideUrl||"",
   installationGuideLabel:cached?.installationGuideLabel||"Notice d'installation",
   includeDrawing:false,includeTechnicalSheet:false,includeInstallationGuide:false,
   customImage:false,accessoryFor:parentId||""
 });

 saveState();
 renderSelection();
 renderRooms();
 renderMarginDashboard();

 if(!cached){
   enrichSelectedPhoto(id,false).catch(err=>console.warn("[enrich after add]",err));
 }
 return id;
}
function removeProduct(id){
  state.selected=state.selected.filter(x=>x.id!==id && x.accessoryFor!==id);
  saveState();renderSelection();renderRooms();renderMarginDashboard();
}

function clampPercent(v){return Math.max(0,Math.min(100,Number(v)||0));}
function clientDiscountRate(){return clampPercent(state.commercial?.clientDiscount||0);}
function discountedValue(v){return Number(v||0)*(1-clientDiscountRate()/100);}
function hasItemDiscountOverride(p){
  return p && p.clientDiscountOverride!==undefined && p.clientDiscountOverride!==null && p.clientDiscountOverride!=="";
}
function itemDiscountRate(p){
  return hasItemDiscountOverride(p)?clampPercent(p.clientDiscountOverride):null;
}
function effectiveDiscountRate(p){
  const own=itemDiscountRate(p);
  return own===null?clientDiscountRate():own;
}

function hasPriceOverride(p){
  return p && p.priceOverride!==undefined && p.priceOverride!==null && p.priceOverride!=="";
}
function articleMerchandisePrice(p){
  if(hasPriceOverride(p))return Math.max(0,Number(p.priceOverride)||0);
  const freight=Math.max(0,Number(p?.mandatoryFreight)||0);
  return Math.max(0,Number(p?.totalPrice||0)-freight);
}
function articleListTotal(p){
  return articleMerchandisePrice(p)+Math.max(0,Number(p?.mandatoryFreight)||0);
}
function catalogPurchaseBase(p){
  const freight=Math.max(0,Number(p?.mandatoryFreight)||0);
  const original=Number(p?.catalogTotalPrice ?? p?.totalPrice ?? 0);
  return Math.max(0,original-freight);
}

function effectiveSaleValue(p){
  const freight=Math.max(0,Number(p?.mandatoryFreight)||0);
  const merchandise=articleMerchandisePrice(p);
  return merchandise*(1-effectiveDiscountRate(p)/100)+freight;
}

function supplierDiscountRate(manufacturer){
  return clampPercent(state.commercial?.supplierDiscounts?.[manufacturer]||0);
}
function selectedCatalogTotal(){
  return state.selected.reduce((sum,p)=>sum+articleListTotal(p),0);
}
function selectedManualTotal(){
  return (state.rooms||[]).reduce((sum,r)=>sum+(r.manual||[]).reduce((s,m)=>s+Number(m.price||0),0),0);
}
function quoteSubtotal(){
  return selectedCatalogTotal()+selectedManualTotal();
}
function purchaseDiscountFor(p){
  const explicit=Number(p?.purchaseDiscount);
  if(Number.isFinite(explicit) && explicit>=0) return clampPercent(explicit);
  if(p?.manufacturer==="Hotbath" && /(?:^|\/)\s*archie\s*(?:\/|$)/i.test(String(p.collection||""))) return 55;
  return supplierDiscountRate(p?.manufacturer);
}
function purchaseCostFor(p){
  const freight=Math.max(0,Number(p?.mandatoryFreight)||0);
  const explicit=Number(p?.purchasePrice);
  if(Number.isFinite(explicit) && explicit>=0)return explicit+freight;
  return catalogPurchaseBase(p)*(1-purchaseDiscountFor(p)/100)+freight;
}
function projectPurchaseCost(){
  return state.selected.reduce((sum,p)=>sum+purchaseCostFor(p),0);
}
function projectFinancials(){
  const productList=selectedCatalogTotal();
  const manualList=selectedManualTotal();
  const list=productList+manualList;

  const productsNet=state.selected.reduce((sum,p)=>sum+effectiveSaleValue(p),0);
  const manualNet=manualList*(1-clientDiscountRate()/100);
  const netBeforeShipping=productsNet+manualNet;
  const discountAmount=list-netBeforeShipping;

  const shipping=Math.max(0,Number(state.commercial?.shippingFee)||0);
  const supplierShipping=Math.max(0,Number(state.commercial?.supplierShippingFee)||0);
  const net=netBeforeShipping+shipping+supplierShipping;

  const purchaseProducts=projectPurchaseCost();
  // Port fournisseur est traité comme un coût refacturé à l'identique : marge neutre.
  const purchase=purchaseProducts+shipping+supplierShipping;

  const margin=productsNet-purchaseProducts;
  const marginOnSales=productsNet>0?margin/productsNet*100:0;
  const marginOnCost=purchaseProducts>0?margin/purchaseProducts*100:0;

  const vatRate=clampPercent(state.commercial?.vatRate??20);
  const vat=net*vatRate/100;

  return {
    list,discountRate:clientDiscountRate(),discountAmount,
    productsNet,manualNet,shipping,supplierShipping,net,
    purchase,purchaseProducts,margin,marginOnSales,marginOnCost,
    vatRate,vat,ttc:net+vat,catalogNet:productsNet
  };
}
function commercialPriceHtml(value,p=null){
  const d=p?effectiveDiscountRate(p):clientDiscountRate();
  const freight=p?Math.max(0,Number(p.mandatoryFreight)||0):0;
  const merchandise=p?articleMerchandisePrice(p):Number(value||0);
  const listTotal=merchandise+freight;
  const netMerchandise=merchandise*(1-d/100);
  const netTotal=netMerchandise+freight;

  if(!d){
    return freight
      ? `<strong>${euro(listTotal)} HT</strong><span class="price-discount">dont ${euro(freight)} port obligatoire</span>`
      : `${euro(listTotal)} HT`;
  }

  const own=p?itemDiscountRate(p):null;
  const label=own===null?`−${d.toLocaleString("fr-FR",{maximumFractionDigits:1})}%`:`article −${d.toLocaleString("fr-FR",{maximumFractionDigits:1})}%`;
  return `<span class="price-list">${euro(listTotal)} HT</span><span class="price-discount">${label}${freight?` · port ${euro(freight)} non remisé`:""}</span><strong>${euro(netTotal)} HT</strong>`;
}
function commercialManufacturers(){
  return [...new Set(state.selected.map(p=>p.manufacturer).filter(Boolean))].sort((x,y)=>x.localeCompare(y,"fr"));
}
function renderMarginDashboard(){
  const root=$("#view-margin"); if(!root)return;
  const cd=$("#clientDiscount"), vat=$("#quoteVatRate"), ship=$("#shippingFee"), supplierShip=$("#supplierShippingFee");
  if(cd) cd.value=clientDiscountRate();
  if(vat) vat.value=clampPercent(state.commercial?.vatRate??20);
  if(ship) ship.value=Math.max(0,Number(state.commercial?.shippingFee)||0);
  if(supplierShip) supplierShip.value=Math.max(0,Number(state.commercial?.supplierShippingFee)||0);

  const makers=commercialManufacturers();
  const supplierHost=$("#supplierDiscounts");
  if(supplierHost){
    supplierHost.innerHTML=makers.length?makers.map(m=>`
      <label class="supplier-discount-row">
        <span><b>${m}</b><small>${m==="Hotbath"?"Remise achat fournisseur · Archie 55 %":m==="Recor"?"Prix net fabricant · public ×2,6":"Remise achat fournisseur"}</small></span>
        <span class="supplier-rate"><input class="supplier-discount-input" data-maker="${m}" type="number" min="0" max="100" step="0.1" value="${supplierDiscountRate(m)}"><em>%</em></span>
      </label>`).join(""):`<div class="margin-empty">Ajoutez des produits au projet pour paramétrer les conditions fournisseur.</div>`;
  }

  const f=projectFinancials();
  const k=$("#marginKpis");
  if(k) k.innerHTML=`
    <div class="margin-kpi"><span>Tarif public projet</span><strong>${euro(f.list)} HT</strong></div>
    <div class="margin-kpi"><span>Vente produits après remises</span><strong>${euro(f.productsNet)} HT</strong><small>Remise globale + éventuelles remises article</small></div>
    <div class="margin-kpi"><span>Frais de port facturés</span><strong>${euro(f.shipping)} HT</strong><small>Ajoutés au devis</small></div>
    <div class="margin-kpi"><span>Port fournisseur</span><strong>${euro(f.supplierShipping)} HT</strong><small>Refacturé à l’identique · marge neutre</small></div>
    <div class="margin-kpi"><span>Coût d'achat produits</span><strong>${euro(f.purchaseProducts)} HT</strong></div>
    <div class="margin-kpi highlight"><span>Marge brute produits</span><strong>${euro(f.margin)} HT</strong><small>Taux de marque ${f.marginOnSales.toLocaleString("fr-FR",{maximumFractionDigits:1})}% · taux de marge ${f.marginOnCost.toLocaleString("fr-FR",{maximumFractionDigits:1})}%</small></div>`;

  const warn=$("#marginWarning");
  if(warn){
    const missing=makers.filter(m=>supplierDiscountRate(m)===0);
    warn.innerHTML=missing.length?`<b>À compléter :</b> remise fournisseur non renseignée pour ${missing.join(", ")}.`:"";
  }

  const detail=$("#marginByManufacturer");
  if(detail){
    const rows=makers.map(m=>{
      const ps=state.selected.filter(p=>p.manufacturer===m);
      const list=ps.reduce((s,p)=>s+articleListTotal(p),0);
      const sale=ps.reduce((s,p)=>s+effectiveSaleValue(p),0);
      const cost=ps.reduce((s,p)=>s+purchaseCostFor(p),0);
      const mg=sale-cost;
      const tm=sale?mg/sale*100:0;
      const purchaseLabel=m==="Hotbath"?`${supplierDiscountRate(m).toLocaleString("fr-FR",{maximumFractionDigits:1})}% · Archie 55%`:m==="Recor"?"Net fourni · coeff. public 2,6":`${supplierDiscountRate(m).toLocaleString("fr-FR",{maximumFractionDigits:1})}%`;
      return `<tr><td>${m}</td><td>${ps.length}</td><td>${euro(list)}</td><td>${purchaseLabel}</td><td>${euro(cost)}</td><td>${euro(sale)}</td><td class="${mg<0?"negative":""}">${euro(mg)} <small>${tm.toLocaleString("fr-FR",{maximumFractionDigits:1})}%</small></td></tr>`;
    }).join("");
    detail.innerHTML=makers.length?`<div class="margin-table-wrap"><table class="margin-table"><thead><tr><th>Fabricant</th><th>Qté</th><th>Tarif HT</th><th>Remise achat</th><th>Coût HT</th><th>Vente nette HT</th><th>Marge brute</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<div class="margin-empty">Aucun produit sélectionné.</div>`;
  }

  $$(".supplier-discount-input").forEach(inp=>inp.oninput=()=>{
    state.commercial.supplierDiscounts[inp.dataset.maker]=clampPercent(inp.value);
    saveState(); renderMarginDashboard();
  });
}
function bindCommercial(){
  const cd=$("#clientDiscount"), vat=$("#quoteVatRate"), ship=$("#shippingFee"), supplierShip=$("#supplierShippingFee");
  if(cd) cd.oninput=()=>{state.commercial.clientDiscount=clampPercent(cd.value);saveState();renderMarginDashboard();};
  if(vat) vat.oninput=()=>{state.commercial.vatRate=clampPercent(vat.value);saveState();renderMarginDashboard();};
  if(ship) ship.oninput=()=>{state.commercial.shippingFee=Math.max(0,Number(ship.value)||0);saveState();renderMarginDashboard();};
  if(supplierShip) supplierShip.oninput=()=>{state.commercial.supplierShippingFee=Math.max(0,Number(supplierShip.value)||0);saveState();renderMarginDashboard();};
  renderMarginDashboard();
}
function quoteRows(){
  const rows=[];
  for(const r of state.rooms){
    const roomProducts=selectedProductsForDocument(r.id);
    const grouped=new Map();
    roomProducts.forEach(p=>{
      const discount=effectiveDiscountRate(p);
      const freight=Math.max(0,Number(p.mandatoryFreight)||0);
      const leadTime=String(p.leadTime||"").trim();
      const key=[p.reference,p.finish,p.manufacturer,discount,freight,leadTime].join("|");
      if(!grouped.has(key)) grouped.set(key,{...p,qty:0,_effectiveDiscount:discount,_freight:freight,_leadTime:leadTime});
      grouped.get(key).qty++;
    });
    for(const p of grouped.values()){
      rows.push({
        room:r.title,reference:p.reference,designation:p.designation,finish:p.finish,
        manufacturer:p.manufacturer,qty:p.qty,
        unit:articleListTotal(p),
        netUnit:effectiveSaleValue(p),
        freight:p._freight||0,
        leadTime:p._leadTime||"",
        manual:false,discount:p._effectiveDiscount
      });
    }
    const mg=new Map();
    (r.manual||[]).forEach(m=>{
      const leadTime=String(m.leadTime||"").trim();
      const key=[m.label,Number(m.price||0),leadTime].join("|");
      if(!mg.has(key)) mg.set(key,{...m,qty:0});
      mg.get(key).qty++;
    });
    for(const m of mg.values()){
      const unit=Number(m.price||0);
      rows.push({
        room:r.title,reference:"",designation:m.label,finish:"",
        manufacturer:"Élément libre",qty:m.qty,unit,
        netUnit:unit*(1-clientDiscountRate()/100),
        freight:0,leadTime:String(m.leadTime||"").trim(),
        manual:true,discount:clientDiscountRate()
      });
    }
  }
  return rows;
}
function quotePages(startNo){
  const rows=quoteRows();
  const f=projectFinancials();
  const perPage=9;
  const pages=Math.max(1,Math.ceil(rows.length/perPage));
  let html="", no=startNo;
  for(let pg=0;pg<pages;pg++){
    const chunk=rows.slice(pg*perPage,(pg+1)*perPage);
    const last=pg===pages-1;
    html+=`<section class="page quote-page">
      <div class="quote-topline"></div>
      <div class="quote-head">
        <div><div class="section-kicker">DEVIS · ${state.project.name||"PROJET CLIENT"}</div><h2>Récapitulatif de la sélection${pages>1?` · ${pg+1}/${pages}`:""}</h2><p>${state.project.client||""}${state.project.location?` · ${state.project.location}`:""}</p></div>
        <div class="quote-brand">Hydropolis${salespersonContactLine()?`<small>${salespersonContactLine("<br>")}</small>`:""}</div>
      </div>
      <table class="quote-table">
        <thead><tr><th>Pièce</th>${state.showSupplierReferences!==false?`<th>Référence</th>`:""}<th>Désignation</th><th>Délai</th><th>Qté</th><th>PU HT</th><th>Remise</th><th>Total HT</th></tr></thead>
        <tbody>${chunk.map(row=>`
          <tr>
            <td>${row.room}</td>
            ${state.showSupplierReferences!==false?`<td>${row.reference||"—"}</td>`:""}
            <td><b>${row.designation}</b><small>${row.manufacturer}${row.finish?` · ${row.finish}`:""}${row.freight?` · port obligatoire ${euro(row.freight)}`:""}</small></td>
            <td>${row.leadTime||"—"}</td>
            <td>${row.qty}</td>
            <td>${euro(row.unit)}</td>
            <td>${row.discount?`${row.discount.toLocaleString("fr-FR",{maximumFractionDigits:1})}%`:"—"}</td>
            <td>${euro(row.netUnit*row.qty)}</td>
          </tr>`).join("") || `<tr><td colspan="${state.showSupplierReferences!==false?8:7}">Aucun produit sélectionné.</td></tr>`}
        </tbody>
      </table>
      ${last?`<div class="quote-totals">
        <div><span>Sous-total tarif HT</span><b>${euro(f.list)}</b></div>
        ${f.discountAmount>0?`<div class="quote-discount"><span>Total remises commerciales</span><b>− ${euro(f.discountAmount)}</b></div>`:""}
        ${f.shipping>0?`<div><span>Frais de port HT</span><b>${euro(f.shipping)}</b></div>`:""}
        ${f.supplierShipping>0?`<div><span>Port fournisseur HT</span><b>${euro(f.supplierShipping)}</b></div>`:""}
        <div class="quote-total-ht"><span>Total HT</span><b>${euro(f.net)}</b></div>
        <div><span>TVA ${f.vatRate.toLocaleString("fr-FR",{maximumFractionDigits:1})}%</span><b>${euro(f.vat)}</b></div>
        <div class="quote-grand-total"><span>GRAND TOTAL TTC</span><b>${euro(f.ttc)}</b></div>
      </div>`:""}
      <div class="quote-bottom"><span>${salespersonContactLine()?`Maison Hydropolis · ${salespersonContactLine(" · ")}`:"Maison Hydropolis"}</span><span>Prix exprimés en euros · devis récapitulatif</span></div>
      <div class="page-no">${no++}</div>
    </section>`;
  }
  return {html,nextNo:no};
}

function renderSelection(){
 $("#selectionCount").textContent=state.rooms.length+" pièce"+(state.rooms.length>1?"s":"")+" · "+state.selected.length+" produit"+(state.selected.length>1?"s":"");
 $("#selectionMini").innerHTML=state.rooms.map(r=>{let ps=state.selected.filter(p=>p.roomId===r.id);return `<div class="mini"><b>${r.title}</b><div class="mini-room">${ps.length} produit${ps.length>1?"s":""}</div>${ps.slice(0,3).map(p=>`<div>${p.reference} · ${euro(p.totalPrice)}</div>`).join("")}</div>`}).join("");
}
function newRoom(){let title=prompt("Nom de la pièce","SDB SUITE");if(!title)return;let id="r"+Date.now();state.rooms.push({id,title,subtitle:"",manual:[]});saveState();renderRoomSelect();renderSelection();renderRooms();renderMarginDashboard();$("#targetRoom").value=id;renderCatalog();}

function safeExactFinishLabel(p){
  try{return exactFinishLabel(p)||p?.finish||""}catch(e){console.warn("[finish label]",p?.reference,e);return p?.finish||""}
}
function safeEffectiveSaleValue(p){
  try{return effectiveSaleValue(p)}catch(e){console.warn("[sale value]",p?.reference,e);return Number(p?.totalPrice||0)}
}
function safeBasinAccessorySuggestions(p,roomId){
  try{return basinAccessorySuggestions(p,roomId)||""}catch(e){console.warn("[basin accessories]",p?.reference,e);return ""}
}
function safeRecorBathOptions(p,roomId){
  try{return recorBathOptions(p,roomId)||""}catch(e){console.warn("[Recor options]",p?.reference,e);return `<div class="room-inline-warning">Options Recor en cours de chargement.</div>`}
}

